package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.robustez.*;import cl.nexbyte.siger.institucional.notificaciones.TareasPersonales;import java.nio.file.Path;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;

class RevisionExcepcionalTest {
 @TempDir Path temp;DatosNucleoTest d;RevisionExcepcionalFixture f;AreasInstitucionalesTest.Reloj clock;
 @BeforeEach void setup()throws Exception{clock=new AreasInstitucionalesTest.Reloj();String mysql=System.getProperty("siger.test.autoridad.mysql");d=new DatosNucleoTest(temp,mysql==null?null:mysql+"_excepcion?sslMode=DISABLED&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000");if(mysql!=null)limpiar();f=new RevisionExcepcionalFixture(d,clock);}
 void limpiar(){d.limpiar();for(var t:List.of("staff_profile_history","identity_event","staff_assignment","staff_account","org_coverage"))d.db.sql.update("DELETE FROM "+t);}
 @AfterEach void close(){if(d!=null){if(System.getProperty("siger.test.autoridad.mysql")!=null)limpiar();d.close();}}
 UUID key(){return UUID.randomUUID();}void denied(int expected,Runnable r){assertEquals(expected,assertThrows(FalloTecnico.class,r::run).status);}
 @Test void habilitacionEspecificaConfirmaSinJefaturaNiAccesoAHermanosYConservaReq(){
  UUID id=f.solicitar();denied(404,()->f.flow.decidir(f.f.a(f.owner),key(),id,new RevisionExcepcional.Decidir(0,"No autoaprobar"),"APROBAR"));f.aprobar(id);assertFalse(f.f.a(f.reviewer).jefeEn("UPR","DEMO_SEDE_A","AREA_A"));denied(404,()->f.f.core.caso(f.f.a(f.reviewer),f.other));
  var r=f.confirmacion(id);denied(404,()->f.flow.confirmar(f.f.a(f.alias),key(),id,r));var key=key();var result=f.flow.confirmar(f.f.a(f.reviewer),key,id,r);assertEquals(result,f.flow.confirmar(f.f.a(f.reviewer),key,id,r));assertEquals("CERRADO",f.f.core.caso(f.f.a(f.reviewer),f.cas).estado());assertEquals("EN_GESTION",f.f.core.caso(f.f.a(f.owner),f.other).estado());assertEquals("ACTIVO",d.db.sql.queryForObject("SELECT state FROM core_requirement WHERE id=?",String.class,f.req.toString()));assertEquals("EXCEPCIONAL",f.f.core.caso(f.f.a(f.reviewer),f.cas).modalidadCierre());assertEquals("UTILIZADA",d.db.sql.queryForObject("SELECT state FROM institution_closure_exception WHERE id=?",String.class,id.toString()));assertEquals(0,d.db.sql.queryForObject("SELECT COUNT(*) FROM core_action WHERE case_id=?",Long.class,f.cas.toString()));
 }
 @Test void reservaNoSeAbrePorLaHabilitacionYCambioDocumentalObligaARevisar(){
  var doc=f.documento("ORDINARIO");UUID id=f.solicitar();f.aprobar(id);var before=f.confirmacion(id);f.f.core.contenidos().proteger(f.f.a(f.owner),key(),f.cas,doc,new ContenidoInstitucional.Proteccion(1,"FIR","Reserva específica de documento"));denied(404,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,before));assertEquals("REVISION_TERMINO",f.f.core.caso(f.f.a(f.owner),f.cas).estado());
  f.f.core.contenidos().proteger(f.f.a(f.owner),key(),f.cas,doc,new ContenidoInstitucional.Proteccion(2,"ORDINARIO","Nueva clasificación acreditada por propietario"));denied(409,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,before));f.flow.confirmar(f.f.a(f.reviewer),key(),id,f.confirmacion(id));
 }
 @Test void obligatoriasYRevisionActualNoSeEludenPorExcepcion(){
  UUID id=f.solicitar();f.aprobar(id);var before=f.confirmacion(id);var tasks=f.f.core.tareas();var task=tasks.crear(f.f.a(f.owner),key(),new TareasPersonales.Edicion(0,"Objetivo obligatorio",null,null,null,null,null,null,"CASO",f.cas,f.reviewer,true,null)).id();denied(409,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,before));denied(409,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,f.confirmacion(id)));tasks.estado(f.f.a(f.reviewer),key(),task,new TareasPersonales.Cambio(0,"COMPLETADA",true));f.flow.confirmar(f.f.a(f.reviewer),key(),id,f.confirmacion(id));assertEquals("CERRADO",f.f.core.caso(f.f.a(f.reviewer),f.cas).estado());
 }
 @Test void caducidadRevocacionYRetiroDeEquipoDenieganAntesDeCerrar(){
  UUID id=f.solicitar();f.aprobar(id);var r=f.confirmacion(id);f.flow.decidir(f.f.a(f.f.f.revisor),key(),id,new RevisionExcepcional.Decidir(1,"Revocación fundada"),"REVOCAR");denied(409,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,r));
  var next=f.solicitar();f.aprobar(next);var fresh=f.confirmacion(next);clock.now=clock.now.plusSeconds(301);denied(409,()->f.flow.confirmar(f.f.a(f.reviewer),key(),next,fresh));assertEquals("REVISION_TERMINO",f.f.core.caso(f.f.a(f.owner),f.cas).estado());
 }
 @Test void rollbackConservaSolicitudYCierreYConcurrenciaRevocarConfirmarTieneUnGanador()throws Exception{
  UUID id=f.solicitar();f.aprobar(id);var r=f.confirmacion(id);assertThrows(IllegalStateException.class,()->d.db.transaction(()->{f.flow.confirmar(f.f.a(f.reviewer),key(),id,r);throw new IllegalStateException("Rollback sintético");}));assertEquals("HABILITADA",d.db.sql.queryForObject("SELECT state FROM institution_closure_exception WHERE id=?",String.class,id.toString()));assertEquals("REVISION_TERMINO",f.f.core.caso(f.f.a(f.owner),f.cas).estado());var start=new CountDownLatch(1);
  try(var pool=Executors.newFixedThreadPool(2)){var close=pool.submit(()->{start.await();try{f.flow.confirmar(f.f.a(f.reviewer),key(),id,r);return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}});var revoke=pool.submit(()->{start.await();try{f.flow.decidir(f.f.a(f.f.f.revisor),key(),id,new RevisionExcepcional.Decidir(1,"Revocación concurrente"),"REVOCAR");return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}});start.countDown();assertNotEquals(close.get(10,TimeUnit.SECONDS),revoke.get(10,TimeUnit.SECONDS));}
 }
 @Test void retirarAccesoDelRevisorOcultaListadosPaquetesYAvisos(){
  UUID id=f.solicitar();f.aprobar(id);var r=f.confirmacion(id);assertTrue(f.flow.autorizarAviso(f.f.a(f.reviewer),id));var resources=new cl.nexbyte.siger.institucional.notificaciones.RecursosNotificacion(d.db,f.f.cat,f.f.core);var notices=new cl.nexbyte.siger.institucional.notificaciones.NotificacionesInstitucionales(d.db,f.f.cat,resources,clock);for(int i=0;i<5;i++)notices.proyectar();assertTrue(notices.listar(f.f.a(f.reviewer),0,50).items().stream().anyMatch(n->n.ruta().equals("revisiones-excepcionales/"+id)));assertEquals(0,notices.proyectar());assertEquals(0,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE resource_type='REV_CIERRE' AND recipient_id=?",Long.class,f.f.ti));
  f.f.core.equipo().retirar(f.f.a(f.owner),key(),f.cas,new EquipoCaso.Retirar(f.rev(),f.reviewer,null,"Retiro explícito de equipo"));assertTrue(f.flow.bandeja(f.f.a(f.reviewer)).isEmpty());assertFalse(f.flow.autorizarAviso(f.f.a(f.reviewer),id));assertTrue(notices.listar(f.f.a(f.reviewer),0,50).items().stream().noneMatch(n->n.ruta().equals("revisiones-excepcionales/"+id)));denied(404,()->f.flow.paquete(f.f.a(f.reviewer),id));denied(404,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,r));
 }
 @Test void raizAnteriorNoInterpretaFacultadNuevaYSuspensionRevocaElUso()throws Exception{
  UUID id=f.solicitar();f.aprobar(id);var r=f.confirmacion(id);long revision=d.db.sql.queryForObject("SELECT revision FROM authority_registry WHERE id=1",Long.class);var payload=d.mapper.readValue(Base64.getDecoder().decode(d.db.sql.queryForObject("SELECT signed_payload FROM authority_batch WHERE revision=?",String.class,revision)),Map.class);var wrong=new LinkedHashMap<String,Object>();payload.forEach((k,v)->wrong.put(k.toString(),v));wrong.put("version","1.4");wrong.put("revision",revision+1);denied(400,()->{try{f.f.importar(wrong);}catch(FalloTecnico e){throw e;}catch(Exception e){throw new RuntimeException(e);}});assertEquals(revision,d.db.sql.queryForObject("SELECT revision FROM authority_registry WHERE id=1",Long.class));
  var cap=f.caps.getFirst();f.caps=List.of(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.FacultadCierre(cap.id(),cap.persona(),cap.unidad(),cap.sede(),cap.area(),cap.materia(),cap.desde(),cap.hasta(),cap.referencia(),cap.sha256(),"SUSPENDIDA"));f.publicar();denied(404,()->f.flow.confirmar(f.f.a(f.reviewer),key(),id,r));assertEquals("REVISION_TERMINO",f.f.core.caso(f.f.a(f.owner),f.cas).estado());
 }
}
